---@class ActivityFashionPreheatingUtils
local ActivityFashionPreheatingUtils = Class('ActivityFashionPreheatingUtils')
-- 获取所有的奖池道具
---@param groupId integer @ 群组id 
---@return FashionPreheatingPoolVo[]
function ActivityFashionPreheatingUtils.GetRewardsGroupVos(groupId)
    groupId = checkInt(groupId)
    local poolVos = {}
    ---@type FashionPreheatingPoolVo[]
    local FashionPreheatingPoolVos =  CfUtils.GetWholeVo(AutoIds.IdSetting6300 , "FashionPreheatingPoolVo")
    for i, v in ipairs(FashionPreheatingPoolVos) do
        if checkInt(v.activityId) == groupId then
            poolVos[#poolVos+1] = v 
        end
    end
    return poolVos
end
