-- 获取大奖池道具
---@return FashionPreheatingPoolVo[]
function ActivityFashionPreheatingUtils.IsBigReards(groupId , goodsId)
    groupId = checkInt(groupId)
    goodsId = checkInt(goodsId)
    local isBig = false
    ---@type FashionPreheatingPoolVo[]
    local FashionPreheatingPoolVos =  CfUtils.GetWholeVo(AutoIds.IdSetting6300 , "FashionPreheatingPoolVo")
    for i, v in ipairs(FashionPreheatingPoolVos) do
        if checkInt(v.activityId) == groupId and checkInt(v.rewardId) == goodsId then
            isBig = v.grandReward > 0 
            break
        end
    end
    return isBig
end

